import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import vm from 'node:vm';import {createHash,randomBytes} from 'node:crypto';import {applyCloudDrive1852Adapter,cloudDrive1852Helpers,cloudDrive1852OriginalSourceSha256} from './cloud-drive-1852-adapter.mjs';import {applyCloudSessionAdapter} from './cloud-session-adapter.mjs';import {applyCloudAttachmentAdapter} from './cloud-attachment-adapter.mjs';
